19	// ---------------------------------------------------------------------------
20	// Tiling constants
21	// ---------------------------------------------------------------------------
22	
23	constexpr int32_t DEFAULT_BLOCK_M = 32;
24	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
25	
