30	namespace ascend_kernel {
31	
32	std::vector<at::Tensor> add_layernorm_quant(
33	    const at::Tensor &x1,
34	    const at::Tensor &x2,
35	    const at::Tensor &gamma,
36	    const at::Tensor &beta,
37	    const c10::optional<at::Tensor> &bias_opt,
38	    const c10::optional<at::Tensor> &scales1_opt,
39	    const c10::optional<at::Tensor> &scales2_opt,
40	    double eps,
41	    int64_t quant_mode)
42	{
43	    // Input validation
44	    TORCH_CHECK(x1.dim() == 2, "x1 must be [M, N]");
45	    TORCH_CHECK(x2.dim() == 2, "x2 must be [M, N]");
46	    TORCH_CHECK(x1.sizes() == x2.sizes(), "x1 and x2 must have the same shape");
47	    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
48	    TORCH_CHECK(beta.dim() == 1, "beta must be [N]");
49	    TORCH_CHECK(
50	        x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
51	            x1.scalar_type() == at::kBFloat16,
52	        "x1 must be float16, float32, or bfloat16");
53	    TORCH_CHECK(x1.is_contiguous(), "x1 must be contiguous");
54	    TORCH_CHECK(x2.is_contiguous(), "x2 must be contiguous");
55	    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
56	    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
57	
58	    int32_t M = static_cast<int32_t>(x1.sizes()[0]);
59	    int32_t N = static_cast<int32_t>(x1.sizes()[1]);
60	
61	    TORCH_CHECK(static_cast<int32_t>(gamma.sizes()[0]) == N,
62	                "gamma shape must match N dimension");
63	    TORCH_CHECK(static_cast<int32_t>(beta.sizes()[0]) == N,
64	                "beta shape must match N dimension");
65	
66	    // Determine bias
67	    bool hasBias = bias_opt.has_value();
68	    at::Tensor bias;
69	    if (hasBias) {
70	        bias = bias_opt.value();
71	        TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
72	    } else {
73	        bias = at::zeros({N}, x1.options());
74	    }
75	
76	    // Determine scales
77	    bool hasScales = (quant_mode == 1);
78	    at::Tensor scales1, scales2;
79	    if (hasScales) {
80	        TORCH_CHECK(scales1_opt.has_value() && scales2_opt.has_value(),
81	                    "scales1 and scales2 required for static quant mode");
82	        scales1 = scales1_opt.value().to(at::kFloat).contiguous();
83	        scales2 = scales2_opt.value().to(at::kFloat).contiguous();
84	    } else {
85	        scales1 = at::ones({N}, at::dtype(at::kFloat).device(x1.device()));
86	        scales2 = at::ones({N}, at::dtype(at::kFloat).device(x1.device()));
87	    }
88	
89	    // Compute tiling
90	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
91	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
92	                                            std::max<int32_t>(1, mNum));
93	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
94	
95	    // Allocate output tensors — y1/y2 as float (clamped), wrapper casts to int8
96	    at::Tensor y1_out = at::empty({M, N}, at::dtype(at::kFloat).device(x1.device()));
97	    at::Tensor y2_out = at::empty({M, N}, at::dtype(at::kFloat).device(x1.device()));
98	    at::Tensor x_out = at::empty_like(x1);
99	    at::Tensor out_scale1 = at::empty({M}, at::dtype(at::kFloat).device(x1.device()));
100	    at::Tensor out_scale2 = at::empty({M}, at::dtype(at::kFloat).device(x1.device()));
101	
102	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
103	    int64_t dtypeFlag = 0;
104	    if (x1.scalar_type() == at::kHalf) {
105	        dtypeFlag = 1;
106	    } else if (x1.scalar_type() == at::kBFloat16) {
107	        dtypeFlag = 2;
108	    }
109	
110	    // Cast gamma, beta to float32
111	    at::Tensor gamma_f32 = gamma.to(at::kFloat).contiguous();
112	    at::Tensor beta_f32 = beta.to(at::kFloat).contiguous();
113	
114	    // Prepare left-value arguments for EXEC_KERNEL_CMD
115	    int32_t blockM = DEFAULT_BLOCK_M;
116	    float epsVal = static_cast<float>(eps);
117	    int64_t quantModeVal = quant_mode;
118	    int64_t hasBiasVal = hasBias ? 1 : 0;
119	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
120	
121	    EXEC_KERNEL_CMD(add_layernorm_quant, blockDim,
122	                    x1, x2, gamma_f32, beta_f32, bias,
123	                    scales1, scales2,
124	                    y1_out, y2_out,
125	                    x_out, out_scale1, out_scale2,
126	                    M, N,
127	                    blockM, usedCoreNum, tasksPerCore,
128	                    epsVal, quantModeVal, hasBiasVal,
129	                    dtypeFlag);
130	
131	    return {y1_out, y2_out, x_out, out_scale1, out_scale2};
132	}
