6	// AscendC AddLayerNormQuant kernel
7	// Add(x1, x2 [+bias]) → LayerNorm(gamma, beta) → Quantize scale + clamp
8	// Outputs clamped float values; model_new_ascendc.py casts to int8
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
