18	template <typename T>
19	__aicore__ inline void LoadToUb(
20	    AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t n)
21	{
22	    AscendC::DataCopyExtParams cp;
23	    cp.blockCount = 1;
24	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
25	    AscendC::DataCopyPadExtParams<T> pp;
26	    pp.isPad = true;
27	    AscendC::DataCopyPad(dst, src, cp, pp);
28	}
29	
30	template <typename T>
31	__aicore__ inline void StoreToGm(
32	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t n)
33	{
34	    AscendC::DataCopyExtParams cp;
35	    cp.blockCount = 1;
36	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
37	    AscendC::DataCopyPad(dst, src, cp);
38	}
