40	template <typename T>
41	__aicore__ inline AscendC::RoundMode RMode()
42	{
43	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
44	    return AscendC::RoundMode::CAST_NONE;
45	}
46	
47	template <typename T>
48	__aicore__ inline void InFp32(
49	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
50	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
51	{
52	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
53	    else {
54	        d = b.Get<float>();
55	        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
56	        AscendC::PipeBarrier<PIPE_V>();
57	    }
58	}
59	
60	template <typename T>
61	__aicore__ inline void OutFp32(
62	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
63	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
64	{
65	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
66	    else { d = b.Get<float>(); AscendC::Duplicate(s, static_cast<T>(0), n); }
67	}
