72	
73	template <typename dataType>
74	class ALQKernel {
75	public:
76	    __aicore__ inline void Init(
77	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
78	        GM_ADDR s1, GM_ADDR s2,
79	        GM_ADDR y1, GM_ADDR y2, GM_ADDR xo,
80	        GM_ADDR os1, GM_ADDR os2,
81	        int32_t M, int32_t N, int32_t bM, int32_t uC, int32_t tpc,
82	        float eps, int64_t qM, int64_t hB)
83	    {
84	        M_=M; N_=N; bM_=bM; uC_=uC; tpc_=tpc; eps_=eps; qM_=qM; hB_=hB;
85	        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), (uint64_t)M*N);
86	        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), (uint64_t)M*N);
87	        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
88	        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
89	        biG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
90	        s1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s1), N);
91	        s2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s2), N);
92	        y1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y1), (uint64_t)M*N);
93	        y2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y2), (uint64_t)M*N);
94	        xoG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xo), (uint64_t)M*N);
95	        o1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(os1), M);
96	        o2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(os2), M);
97	        if ASCEND_IS_AIV { BufInit(); }
98	    }
99	
100	    __aicore__ inline void BufInit()
101	    {
102	        sb_ = bM_ / AscendC::GetSubBlockNum();
103	        p_.InitBuffer(iQ1_, BUFFER_NUM, N_*sizeof(dataType));
104	        p_.InitBuffer(iQ2_, BUFFER_NUM, N_*sizeof(dataType));
105	        p_.InitBuffer(oQX_, BUFFER_NUM, N_*sizeof(dataType));
106	        p_.InitBuffer(oQY1_, BUFFER_NUM, N_*sizeof(float));
107	        p_.InitBuffer(oQY2_, BUFFER_NUM, N_*sizeof(float));
108	        p_.InitBuffer(oQS_, BUFFER_NUM, 2*sizeof(float));
109	        p_.InitBuffer(bGam_, N_*sizeof(float)); p_.InitBuffer(bBet_, N_*sizeof(float));
110	        if (qM_==1) { p_.InitBuffer(bS1_, N_*sizeof(float)); p_.InitBuffer(bS2_, N_*sizeof(float)); }
111	        if (hB_) p_.InitBuffer(bBi_, N_*sizeof(dataType));
112	        if constexpr (!std::is_same_v<dataType, float>) {
113	            p_.InitBuffer(bC1_, N_*sizeof(float)); p_.InitBuffer(bC2_, N_*sizeof(float));
114	            p_.InitBuffer(bCX_, N_*sizeof(float));
115	            if (hB_) p_.InitBuffer(bCB_, N_*sizeof(float));
116	        }
117	        p_.InitBuffer(bwA_, N_*sizeof(float)); p_.InitBuffer(bwB_, N_*sizeof(float));
118	        p_.InitBuffer(bwC_, N_*sizeof(float)); p_.InitBuffer(bwD_, N_*sizeof(float));
119	        p_.InitBuffer(bRed_, N_*sizeof(float)); p_.InitBuffer(bSum_, 16*sizeof(float));
120	        p_.InitBuffer(bClp_, N_*sizeof(float));
121	        p_.InitBuffer(bQntTmp_, N_*sizeof(float));
122	
123	        gL_ = bGam_.Get<float>(); LoadToUb(gL_, gG_, (uint32_t)N_);
124	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
125	        bL_ = bBet_.Get<float>(); LoadToUb(bL_, bG_, (uint32_t)N_);
126	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
127	        if (qM_==1) {
128	            s1L_ = bS1_.Get<float>(); LoadToUb(s1L_, s1G_, (uint32_t)N_);
129	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
130	            s2L_ = bS2_.Get<float>(); LoadToUb(s2L_, s2G_, (uint32_t)N_);
131	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
132	        }
133	        if (hB_) {
134	            biL_ = bBi_.Get<dataType>(); LoadToUb(biL_, biG_, (uint32_t)N_);
135	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
136	            InFp32<dataType>(bFL_, biL_, bCB_, N_);
137	        }
138	    }
139	
140	    __aicore__ inline void Process()
141	    {
142	        if ASCEND_IS_AIV {
143	            int c = AscendC::GetBlockIdx()/AscendC::GetSubBlockNum();
144	            int s = AscendC::GetSubBlockIdx();
145	            for (int li=0; li<tpc_; ++li) {
146	                int bx = c*tpc_+li; if (bx*bM_>=M_) continue;
147	                for (int r=0; r<sb_; ++r) {
148	                    int row = bx*bM_+s*sb_+r; if (row<M_) Row(row);
149	                }
150	            }
151	        }
152	    }
153	
154	private:
155	    __aicore__ inline void Row(int32_t row) { CopyIn(row); Comp(); CopyOut(row); }
156	
157	    __aicore__ inline void CopyIn(int32_t row)
158	    {
159	        tX1_=iQ1_.AllocTensor<dataType>();
160	        LoadToUb(tX1_, x1G_[(uint64_t)row*N_], (uint32_t)N_); iQ1_.EnQue(tX1_);
161	        tX2_=iQ2_.AllocTensor<dataType>();
162	        LoadToUb(tX2_, x2G_[(uint64_t)row*N_], (uint32_t)N_); iQ2_.EnQue(tX2_);
163	    }
164	
165	    __aicore__ inline void Comp()
166	    {
167	        tXO_=oQX_.AllocTensor<dataType>();
168	        tY1_=oQY1_.AllocTensor<float>();
169	        tY2_=oQY2_.AllocTensor<float>();
170	        tS_=oQS_.AllocTensor<float>();
171	        wA_=bwA_.Get<float>(); wB_=bwB_.Get<float>(); wC_=bwC_.Get<float>();
172	        wD_=bwD_.Get<float>();
173	        wR_=bRed_.Get<float>(); wS_=bSum_.Get<float>(); wL_=bClp_.Get<float>();
174	
175	        tX1_=iQ1_.DeQue<dataType>(); tX2_=iQ2_.DeQue<dataType>();
176	        InFp32<dataType>(x1F_, tX1_, bC1_, N_);
177	        InFp32<dataType>(x2F_, tX2_, bC2_, N_);
178	        OutFp32<dataType>(xoF_, tXO_, bCX_, N_);
179	
180	        // PHASE 1: x_out = x1 + x2 [+ bias]
181	        AscendC::Add(xoF_, x1F_, x2F_, N_);
182	        if (hB_) AscendC::Add(xoF_, xoF_, bFL_, N_);
183	        if constexpr (!std::is_same_v<dataType, float>) {
184	            AscendC::Cast(tXO_, xoF_, RMode<dataType>(), N_); AscendC::PipeBarrier<PIPE_V>();
185	        }
186	        oQX_.EnQue(tXO_);
187	
188	        // PHASE 2: stats
189	        AscendC::ReduceSum<float>(wS_, xoF_, wR_, N_);
190	        AscendC::PipeBarrier<PIPE_V>(); float sx=wS_.GetValue(0);
191	        wR_=bRed_.Get<float>();
192	        AscendC::Mul(wA_, xoF_, xoF_, N_);
193	        AscendC::ReduceSum<float>(wS_, wA_, wR_, N_);
194	        AscendC::PipeBarrier<PIPE_V>(); float sx2=wS_.GetValue(0);
195	        float inv=1.0f/(float)N_, mv=sx*inv, vv=sx2*inv - mv*mv;
196	        AscendC::Duplicate(wS_, vv+eps_, 1);
197	        AscendC::Rsqrt(wS_, wS_, 1); AscendC::PipeBarrier<PIPE_ALL>();
198	        float rv=wS_.GetValue(0);
199	
200	        // PHASE 3: layernorm
201	        AscendC::Adds(wA_, xoF_, -mv, N_); AscendC::Muls(wA_, wA_, rv, N_);
202	        AscendC::Mul(wB_, wA_, gL_, N_); AscendC::Add(wB_, wB_, bL_, N_);
203	
204	        // PHASE 4: quantize → clamped float output
205	        float s1, s2;
206	        if (qM_==1) {
207	            AscendC::Mul(wA_, wB_, s1L_, N_); s1 = Quant(wA_, tY1_);
208	            AscendC::Mul(wA_, wB_, s2L_, N_); s2 = Quant(wA_, tY2_);
209	        } else {
210	            s1 = Quant(wB_, tY1_);
211	            AscendC::Duplicate(tY2_, 0.0f, N_); s2 = s1;
212	        }
213	
214	        oQY1_.EnQue(tY1_); oQY2_.EnQue(tY2_);
215	        tS_.SetValue(0,s1); tS_.SetValue(1,s2); oQS_.EnQue(tS_);
216	        iQ1_.FreeTensor(tX1_); iQ2_.FreeTensor(tX2_);
217	    }
218	
219	    __aicore__ inline float Quant(AscendC::LocalTensor<float> &src,
220	                                   AscendC::LocalTensor<float> &dst)
221	    {
222	        // Use wC_ for abs/scale to avoid aliasing with src.
223	        // Use wD_ for Max intermediate to avoid corrupting src or wB_.
224	        AscendC::Abs(wC_, src, N_);
225	        wR_=bRed_.Get<float>();
226	        AscendC::ReduceMax<float>(wS_, wC_, wR_, N_);
227	        AscendC::PipeBarrier<PIPE_V>();
228	        float sc=wS_.GetValue(0)/127.0f;
229	        float is=1.0f/(sc+1e-12f);
230	        AscendC::Muls(wC_, src, is, N_);
231	        AscendC::Duplicate(wL_, -128.0f, N_); AscendC::PipeBarrier<PIPE_V>();
232	        AscendC::Max(wD_, wC_, wL_, N_);
233	        AscendC::Duplicate(wL_, 127.0f, N_); AscendC::PipeBarrier<PIPE_V>();
234	        AscendC::Min(dst, wD_, wL_, N_);
235	        return sc;
236	    }
237	
238	    __aicore__ inline void CopyOut(int32_t row)
239	    {
240	        tXO_=oQX_.DeQue<dataType>(); StoreToGm(xoG_[(uint64_t)row*N_], tXO_, (uint32_t)N_); oQX_.FreeTensor(tXO_);
241	        tY1_=oQY1_.DeQue<float>(); StoreToGm(y1G_[(uint64_t)row*N_], tY1_, (uint32_t)N_); oQY1_.FreeTensor(tY1_);
242	        tY2_=oQY2_.DeQue<float>(); StoreToGm(y2G_[(uint64_t)row*N_], tY2_, (uint32_t)N_); oQY2_.FreeTensor(tY2_);
243	        tS_=oQS_.DeQue<float>();
244	        float sv1=tS_.GetValue(0), sv2=tS_.GetValue(1); oQS_.FreeTensor(tS_);
245	        AscendC::LocalTensor<float> sb=bSum_.Get<float>();
246	        AscendC::Duplicate(sb, sv1, 1); StoreToGm(o1G_[row], sb, 1);
247	        AscendC::Duplicate(sb, sv2, 1); StoreToGm(o2G_[row], sb, 1);
248	    }
249	
250	    int32_t M_=0,N_=0,bM_=0,uC_=0,tpc_=0,sb_=0;
251	    float eps_=0; int64_t qM_=0,hB_=0;
252	    AscendC::TPipe p_;
253	    AscendC::GlobalTensor<dataType> x1G_,x2G_,biG_,xoG_;
254	    AscendC::GlobalTensor<float> gG_,bG_,s1G_,s2G_,y1G_,y2G_,o1G_,o2G_;
255	    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> iQ1_,iQ2_;
256	    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> oQX_,oQY1_,oQY2_,oQS_;
257	    AscendC::TBuf<AscendC::TPosition::VECCALC> bGam_,bBet_,bS1_,bS2_,bBi_;
258	    AscendC::TBuf<AscendC::TPosition::VECCALC> bC1_,bC2_,bCX_,bCB_,bwA_,bwB_,bwC_,bwD_,bRed_,bSum_,bClp_,bQntTmp_;
259	    AscendC::LocalTensor<dataType> tX1_,tX2_,tXO_,biL_;
260	    AscendC::LocalTensor<float> tY1_,tY2_,tS_,gL_,bL_,s1L_,s2L_,bFL_;
261	    AscendC::LocalTensor<float> x1F_,x2F_,xoF_,wA_,wB_,wC_,wD_,wR_,wS_,wL_;
262	};
263	
264	template <template <typename> class K>
265	__aicore__ inline void D(
266	    GM_ADDR x1,GM_ADDR x2,GM_ADDR g,GM_ADDR b,GM_ADDR bi,GM_ADDR s1,GM_ADDR s2,
267	    GM_ADDR y1,GM_ADDR y2,GM_ADDR xo,GM_ADDR o1,GM_ADDR o2,
268	    int32_t M,int32_t N,int32_t bM,int32_t uC,int32_t tp,
269	    float e,int64_t qM,int64_t hB,int64_t fl)
270	{
271	    if(fl==0){K<float>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
272	    else if(fl==1){K<half>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
273	    else{K<bfloat16_t>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
274	}
