// AscendC DuaQuantizeAddLayerNorm kernel
// x1 + x2 + bias -> LayerNorm(gamma, beta) -> Dual Quantize(int8) + x_out
// Computation flow per row:
//   Phase 1: x_sum = x1 + x2 + bias, stats (sum, sum_sq)
//   Phase 2: LayerNorm (mean, rstd, gamma, beta)
//   Phase 3: Dual quantize (div or mul) + x_out = round(x_sum)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadToUb(
    AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t n)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPadExtParams<T> pp;
    pp.isPad = true;
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreToGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t n)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
__aicore__ inline AscendC::RoundMode RMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void InFp32(
    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
{
    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
    else {
        d = b.Get<float>();
        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void OutFp32(
    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
{
    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
    else { d = b.Get<float>(); AscendC::Duplicate(s, static_cast<T>(0), n); }
}

// =========================================================================
// Kernel
// =========================================================================

template <typename dataType>
class DQALNKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
        GM_ADDR s1, GM_ADDR s2, GM_ADDR zp1, GM_ADDR zp2,
        GM_ADDR y1, GM_ADDR y2, GM_ADDR xo,
        int32_t M, int32_t N, int32_t bM, int32_t uC, int32_t tpc,
        float eps, int64_t divMode, int64_t dtypeFlag)
    {
        M_=M; N_=N; bM_=bM; uC_=uC; tpc_=tpc; eps_=eps;
        divMode_=divMode; dtypeFlag_=dtypeFlag;

        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), (uint64_t)M*N);
        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), (uint64_t)M*N);
        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
        biG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
        s1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s1), N);
        s2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s2), N);
        zp1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp1), N);
        zp2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp2), N);
        y1G_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1), (uint64_t)M*N);
        y2G_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2), (uint64_t)M*N);
        xoG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xo), (uint64_t)M*N);

        if ASCEND_IS_AIV { BufInit(); }
    }

    __aicore__ inline void BufInit()
    {
        sb_ = bM_ / AscendC::GetSubBlockNum();
        p_.InitBuffer(iQ1_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(iQ2_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(iQB_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(oQY1_, BUFFER_NUM, N_*sizeof(int8_t));
        p_.InitBuffer(oQY2_, BUFFER_NUM, N_*sizeof(int8_t));
        p_.InitBuffer(oQX_, BUFFER_NUM, N_*sizeof(dataType));

        // Pre-load static data
        p_.InitBuffer(bGam_, N_*sizeof(float));
        p_.InitBuffer(bBet_, N_*sizeof(float));
        p_.InitBuffer(bS1_, N_*sizeof(float));
        p_.InitBuffer(bS2_, N_*sizeof(float));
        p_.InitBuffer(bZ1_, N_*sizeof(float));
        p_.InitBuffer(bZ2_, N_*sizeof(float));
        p_.InitBuffer(bBi_, N_*sizeof(dataType));

        // Work buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            p_.InitBuffer(bC1_, N_*sizeof(float));
            p_.InitBuffer(bC2_, N_*sizeof(float));
            p_.InitBuffer(bCB_, N_*sizeof(float));
            p_.InitBuffer(bCX_, N_*sizeof(float));
        }
        p_.InitBuffer(bwA_, N_*sizeof(float));
        p_.InitBuffer(bwB_, N_*sizeof(float));
        p_.InitBuffer(bwC_, N_*sizeof(float));
        p_.InitBuffer(bwD_, N_*sizeof(float));
        p_.InitBuffer(bRed_, N_*sizeof(float));
        p_.InitBuffer(bSum_, 16*sizeof(float));
        p_.InitBuffer(bClp_, N_*sizeof(float));
        p_.InitBuffer(bRnd_, N_*sizeof(float));

        // Pre-load gamma, beta
        gL_ = bGam_.Get<float>();
        LoadToUb(gL_, gG_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        bL_ = bBet_.Get<float>();
        LoadToUb(bL_, bG_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();

        // Pre-load scales
        s1L_ = bS1_.Get<float>();
        LoadToUb(s1L_, s1G_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        s2L_ = bS2_.Get<float>();
        LoadToUb(s2L_, s2G_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();

        // Pre-load zero points
        z1L_ = bZ1_.Get<float>();
        LoadToUb(z1L_, zp1G_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        z2L_ = bZ2_.Get<float>();
        LoadToUb(z2L_, zp2G_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();

        // Pre-load bias and cast to fp32
        biL_ = bBi_.Get<dataType>();
        LoadToUb(biL_, biG_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        InFp32<dataType>(bFL_, biL_, bCB_, N_);
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int c = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int s = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tpc_; ++li) {
                int bx = c * tpc_ + li;
                if (bx * bM_ >= M_) continue;
                for (int r = 0; r < sb_; ++r) {
                    int row = bx * bM_ + s * sb_ + r;
                    if (row < M_) Row(row);
                }
            }
        }
    }

private:
    __aicore__ inline void Row(int32_t row) { CopyIn(row); Comp(); CopyOut(row); }

    __aicore__ inline void CopyIn(int32_t row)
    {
        tX1_ = iQ1_.AllocTensor<dataType>();
        LoadToUb(tX1_, x1G_[(uint64_t)row * N_], (uint32_t)N_);
        iQ1_.EnQue(tX1_);

        tX2_ = iQ2_.AllocTensor<dataType>();
        LoadToUb(tX2_, x2G_[(uint64_t)row * N_], (uint32_t)N_);
        iQ2_.EnQue(tX2_);
    }

    __aicore__ inline void Comp()
    {
        tY1_ = oQY1_.AllocTensor<int8_t>();
        tY2_ = oQY2_.AllocTensor<int8_t>();
        tXO_ = oQX_.AllocTensor<dataType>();

        wA_ = bwA_.Get<float>(); wB_ = bwB_.Get<float>();
        wC_ = bwC_.Get<float>(); wD_ = bwD_.Get<float>();
        wR_ = bRed_.Get<float>(); wS_ = bSum_.Get<float>();
        wL_ = bClp_.Get<float>(); wN_ = bRnd_.Get<float>();

        tX1_ = iQ1_.DeQue<dataType>();
        tX2_ = iQ2_.DeQue<dataType>();

        InFp32<dataType>(x1F_, tX1_, bC1_, N_);
        InFp32<dataType>(x2F_, tX2_, bC2_, N_);
        OutFp32<dataType>(xoF_, tXO_, bCX_, N_);

        // =====================================================================
        // Phase 1: Compute x_sum = x1 + x2 + bias, stats
        // =====================================================================

        AscendC::Add(wA_, x1F_, x2F_, N_);
        AscendC::Add(wA_, wA_, bFL_, N_);  // wA_ = x_sum

        // Stats: sum(x_sum) and sum(x_sum^2)
        AscendC::ReduceSum<float>(wS_, wA_, wR_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float sx = wS_.GetValue(0);

        wR_ = bRed_.Get<float>();
        AscendC::Mul(wB_, wA_, wA_, N_);
        AscendC::ReduceSum<float>(wS_, wB_, wR_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float sx2 = wS_.GetValue(0);

        float inv = 1.0f / (float)N_;
        float mv = sx * inv;
        float vv = sx2 * inv - mv * mv;

        // rstd = 1 / sqrt(var + eps)
        AscendC::Duplicate(wS_, vv + eps_, 1);
        AscendC::Rsqrt(wS_, wS_, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float rv = wS_.GetValue(0);

        // =====================================================================
        // Phase 2: LayerNorm: y = (x_sum - mean) * rstd * gamma + beta
        // =====================================================================

        AscendC::Adds(wB_, wA_, -mv, N_);       // centered = x_sum - mean
        AscendC::Muls(wB_, wB_, rv, N_);        // normalized
        AscendC::Mul(wC_, wB_, gL_, N_);        // scaled by gamma
        AscendC::Add(wD_, wC_, bL_, N_);        // y_norm = scaled + beta
        // wD_ = y_norm (LayerNorm output)

        // =====================================================================
        // Phase 3: x_out = round(x_sum).cast(dtype)
        // =====================================================================

        // Round x_sum to nearest integer
        AscendC::Round(wC_, wA_, wN_, N_);
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(xoF_, wC_, N_);
        } else {
            AscendC::Cast(tXO_, wC_, RMode<dataType>(), N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
        oQX_.EnQue(tXO_);

        // =====================================================================
        // Phase 4: Dual Quantization
        // =====================================================================

        // ---- y1 quant ----
        // y1_q = div_mode ? y / scale1 : y * scale1
        if (divMode_) {
            AscendC::Div(wB_, wD_, s1L_, N_);
        } else {
            AscendC::Mul(wB_, wD_, s1L_, N_);
        }
        // y1_q += zp1
        AscendC::Add(wB_, wB_, z1L_, N_);

        // Round to nearest, clamp [-128, 127], cast to int8
        AscendC::Round(wC_, wB_, wN_, N_);
        AscendC::Duplicate(wL_, -128.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Max(wA_, wC_, wL_, N_);
        AscendC::Duplicate(wL_, 127.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Min(wC_, wA_, wL_, N_);
        AscendC::Cast(tY1_, wC_, AscendC::RoundMode::CAST_NONE, N_);
        AscendC::PipeBarrier<PIPE_V>();
        oQY1_.EnQue(tY1_);

        // ---- y2 quant ----
        if (divMode_) {
            AscendC::Div(wB_, wD_, s2L_, N_);
        } else {
            AscendC::Mul(wB_, wD_, s2L_, N_);
        }
        AscendC::Add(wB_, wB_, z2L_, N_);

        AscendC::Round(wC_, wB_, wN_, N_);
        AscendC::Duplicate(wL_, -128.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Max(wA_, wC_, wL_, N_);
        AscendC::Duplicate(wL_, 127.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Min(wC_, wA_, wL_, N_);
        AscendC::Cast(tY2_, wC_, AscendC::RoundMode::CAST_NONE, N_);
        AscendC::PipeBarrier<PIPE_V>();
        oQY2_.EnQue(tY2_);

        iQ1_.FreeTensor(tX1_);
        iQ2_.FreeTensor(tX2_);
    }

    __aicore__ inline void CopyOut(int32_t row)
    {
        tY1_ = oQY1_.DeQue<int8_t>();
        tY2_ = oQY2_.DeQue<int8_t>();
        tXO_ = oQX_.DeQue<dataType>();

        StoreToGm(y1G_[(uint64_t)row * N_], tY1_, (uint32_t)N_);
        oQY1_.FreeTensor(tY1_);
        StoreToGm(y2G_[(uint64_t)row * N_], tY2_, (uint32_t)N_);
        oQY2_.FreeTensor(tY2_);
        StoreToGm(xoG_[(uint64_t)row * N_], tXO_, (uint32_t)N_);
        oQX_.FreeTensor(tXO_);
    }

    int32_t M_=0, N_=0, bM_=0, uC_=0, tpc_=0, sb_=0;
    float eps_=0; int64_t divMode_=0, dtypeFlag_=0;
    AscendC::TPipe p_;
    AscendC::GlobalTensor<dataType> x1G_, x2G_, biG_, xoG_;
    AscendC::GlobalTensor<float> gG_, bG_, s1G_, s2G_, zp1G_, zp2G_;
    AscendC::GlobalTensor<int8_t> y1G_, y2G_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> iQ1_, iQ2_, iQB_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> oQY1_, oQY2_, oQX_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bGam_, bBet_, bS1_, bS2_, bZ1_, bZ2_, bBi_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bC1_, bC2_, bCB_, bCX_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bwA_, bwB_, bwC_, bwD_, bRed_, bSum_, bClp_, bRnd_;
    AscendC::LocalTensor<dataType> tX1_, tX2_, tXO_, biL_;
    AscendC::LocalTensor<int8_t> tY1_, tY2_;
    AscendC::LocalTensor<float> gL_, bL_, s1L_, s2L_, z1L_, z2L_, bFL_;
    AscendC::LocalTensor<float> x1F_, x2F_, xoF_, wA_, wB_, wC_, wD_, wR_, wS_, wL_, wN_;
};

template <template <typename> class K>
__aicore__ inline void Dispatch(
    GM_ADDR x1,  GM_ADDR x2,  GM_ADDR g,  GM_ADDR b,  GM_ADDR bi,
    GM_ADDR s1,  GM_ADDR s2,  GM_ADDR z1, GM_ADDR z2,
    GM_ADDR y1,  GM_ADDR y2,  GM_ADDR xo,
    int32_t M,   int32_t N,   int32_t bM, int32_t uC, int32_t tp,
    float e,     int64_t dM,  int64_t fl)
{
    if (fl == 0) {
        K<float> k;
        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
        k.Process();
    } else if (fl == 1) {
        K<half> k;
        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
        k.Process();
    } else {
        K<bfloat16_t> k;
        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
        k.Process();
    }
}

extern "C" __global__ __aicore__ void dua_quantize_add_layernorm(
    GM_ADDR x1,  GM_ADDR x2,  GM_ADDR g,  GM_ADDR b,  GM_ADDR bi,
    GM_ADDR s1,  GM_ADDR s2,  GM_ADDR z1, GM_ADDR z2,
    GM_ADDR y1,  GM_ADDR y2,  GM_ADDR xo,
    int32_t M,   int32_t N,   int32_t bM, int32_t uC, int32_t tp,
    float e,     int64_t dM,  int64_t fl)
{
    Dispatch<DQALNKernel>(
        x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
}
