// DuaQuantizeAddLayerNorm host — tiling + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_dua_quantize_add_layernorm.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 32;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::vector<at::Tensor> dua_quantize_add_layernorm(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &gamma,
    const at::Tensor &beta,
    const at::Tensor &bias,
    const at::Tensor &scales1,
    const at::Tensor &scales2,
    const at::Tensor &zero_points1,
    const at::Tensor &zero_points2,
    double eps,
    int64_t axis,
    int64_t additional_output)
{
    // Input validation
    TORCH_CHECK(x1.dim() == 2, "x1 must be [M, N]");
    TORCH_CHECK(x2.dim() == 2, "x2 must be [M, N]");
    TORCH_CHECK(x1.sizes() == x2.sizes(), "x1 and x2 must have the same shape");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be [N]");
    TORCH_CHECK(bias.dim() == 1, "bias must be [N]");
    TORCH_CHECK(scales1.dim() == 1, "scales1 must be [N]");
    TORCH_CHECK(scales2.dim() == 1, "scales2 must be [N]");
    TORCH_CHECK(zero_points1.dim() == 1, "zero_points1 must be [N]");
    TORCH_CHECK(zero_points2.dim() == 1, "zero_points2 must be [N]");
    TORCH_CHECK(
        x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
            x1.scalar_type() == at::kBFloat16,
        "x1 must be float16, float32, or bfloat16");
    TORCH_CHECK(x1.is_contiguous(), "x1 must be contiguous");
    TORCH_CHECK(x2.is_contiguous(), "x2 must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(scales1.is_contiguous(), "scales1 must be contiguous");
    TORCH_CHECK(scales2.is_contiguous(), "scales2 must be contiguous");
    TORCH_CHECK(zero_points1.is_contiguous(), "zero_points1 must be contiguous");
    TORCH_CHECK(zero_points2.is_contiguous(), "zero_points2 must be contiguous");

    int32_t M = static_cast<int32_t>(x1.sizes()[0]);
    int32_t N = static_cast<int32_t>(x1.sizes()[1]);

    TORCH_CHECK(static_cast<int32_t>(gamma.sizes()[0]) == N,
                "gamma shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(beta.sizes()[0]) == N,
                "beta shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(bias.sizes()[0]) == N,
                "bias shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(scales1.sizes()[0]) == N,
                "scales1 shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(scales2.sizes()[0]) == N,
                "scales2 shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(zero_points1.sizes()[0]) == N,
                "zero_points1 shape must match N dimension");
    TORCH_CHECK(static_cast<int32_t>(zero_points2.sizes()[0]) == N,
                "zero_points2 shape must match N dimension");

    // Determine quantization mode: AXIS_MUL_MODE = -65535
    constexpr int64_t AXIS_MUL_MODE = -65535;
    int64_t divMode = (axis != AXIS_MUL_MODE) ? 1 : 0;

    // Compute tiling
    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                            std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Allocate output tensors
    at::Tensor y1_out = at::empty({M, N},
        at::TensorOptions().dtype(at::kChar).device(x1.device()));
    at::Tensor y2_out = at::empty({M, N},
        at::TensorOptions().dtype(at::kChar).device(x1.device()));
    at::Tensor x_out = at::empty_like(x1);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x1.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x1.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Cast gamma, beta, scales, zero_points to float32
    at::Tensor gamma_f32 = gamma.to(at::kFloat).contiguous();
    at::Tensor beta_f32 = beta.to(at::kFloat).contiguous();
    at::Tensor scales1_f32 = scales1.to(at::kFloat).contiguous();
    at::Tensor scales2_f32 = scales2.to(at::kFloat).contiguous();
    at::Tensor zp1_f32 = zero_points1.to(at::kFloat).contiguous();
    at::Tensor zp2_f32 = zero_points2.to(at::kFloat).contiguous();

    // Prepare left-value arguments for EXEC_KERNEL_CMD
    int32_t blockM = DEFAULT_BLOCK_M;
    float epsVal = static_cast<float>(eps);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(dua_quantize_add_layernorm, blockDim,
                    x1, x2, gamma_f32, beta_f32, bias,
                    scales1_f32, scales2_f32,
                    zp1_f32, zp2_f32,
                    y1_out, y2_out, x_out,
                    M, N,
                    blockM, usedCoreNum, tasksPerCore,
                    epsVal, divMode, dtypeFlag);

    return {y1_out, y2_out, x_out};
}

}  // namespace ascend_kernel
