6	// AscendC DuaQuantizeAddLayerNorm kernel
7	// x1 + x2 + bias -> LayerNorm(gamma, beta) -> Dual Quantize(int8) + x_out
8	// Computation flow per row:
9	//   Phase 1: x_sum = x1 + x2 + bias, stats (sum, sum_sq)
10	//   Phase 2: LayerNorm (mean, rstd, gamma, beta)
11	//   Phase 3: Dual quantize (div or mul) + x_out = round(x_sum)
12	
13	#include "kernel_operator.h"
14	
15	constexpr int32_t BUFFER_NUM = 1;
16	
17	// =========================================================================
18	// Helpers
19	// =========================================================================
20	
21	template <typename T>
22	__aicore__ inline void LoadToUb(
23	    AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t n)
24	{
25	    AscendC::DataCopyExtParams cp;
26	    cp.blockCount = 1;
27	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
28	    AscendC::DataCopyPadExtParams<T> pp;
29	    pp.isPad = true;
30	    AscendC::DataCopyPad(dst, src, cp, pp);
31	}
32	
33	template <typename T>
34	__aicore__ inline void StoreToGm(
35	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t n)
36	{
37	    AscendC::DataCopyExtParams cp;
38	    cp.blockCount = 1;
39	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
40	    AscendC::DataCopyPad(dst, src, cp);
41	}
42	
43	template <typename T>
44	__aicore__ inline AscendC::RoundMode RMode()
45	{
46	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
47	    return AscendC::RoundMode::CAST_NONE;
48	}
49	
50	template <typename T>
51	__aicore__ inline void InFp32(
52	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
53	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
54	{
55	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
56	    else {
57	        d = b.Get<float>();
58	        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
59	        AscendC::PipeBarrier<PIPE_V>();
60	    }
61	}
62	
63	template <typename T>
64	__aicore__ inline void OutFp32(
65	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
66	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
67	{
68	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
69	    else { d = b.Get<float>(); AscendC::Duplicate(s, static_cast<T>(0), n); }
70	}
71	
72	// =========================================================================
73	// Kernel
74	// =========================================================================
75	
76	template <typename dataType>
77	class DQALNKernel {
78	public:
79	    __aicore__ inline void Init(
80	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
81	        GM_ADDR s1, GM_ADDR s2, GM_ADDR zp1, GM_ADDR zp2,
82	        GM_ADDR y1, GM_ADDR y2, GM_ADDR xo,
83	        int32_t M, int32_t N, int32_t bM, int32_t uC, int32_t tpc,
84	        float eps, int64_t divMode, int64_t dtypeFlag)
85	    {
86	        M_=M; N_=N; bM_=bM; uC_=uC; tpc_=tpc; eps_=eps;
87	        divMode_=divMode; dtypeFlag_=dtypeFlag;
88	
89	        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), (uint64_t)M*N);
90	        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), (uint64_t)M*N);
91	        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
92	        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
93	        biG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
94	        s1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s1), N);
95	        s2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s2), N);
96	        zp1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp1), N);
97	        zp2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp2), N);
98	        y1G_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1), (uint64_t)M*N);
99	        y2G_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2), (uint64_t)M*N);
100	        xoG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xo), (uint64_t)M*N);
101	
102	        if ASCEND_IS_AIV { BufInit(); }
103	    }
104	
105	    __aicore__ inline void BufInit()
106	    {
107	        sb_ = bM_ / AscendC::GetSubBlockNum();
108	        p_.InitBuffer(iQ1_, BUFFER_NUM, N_*sizeof(dataType));
109	        p_.InitBuffer(iQ2_, BUFFER_NUM, N_*sizeof(dataType));
110	        p_.InitBuffer(iQB_, BUFFER_NUM, N_*sizeof(dataType));
111	        p_.InitBuffer(oQY1_, BUFFER_NUM, N_*sizeof(int8_t));
112	        p_.InitBuffer(oQY2_, BUFFER_NUM, N_*sizeof(int8_t));
113	        p_.InitBuffer(oQX_, BUFFER_NUM, N_*sizeof(dataType));
114	
115	        // Pre-load static data
116	        p_.InitBuffer(bGam_, N_*sizeof(float));
117	        p_.InitBuffer(bBet_, N_*sizeof(float));
118	        p_.InitBuffer(bS1_, N_*sizeof(float));
119	        p_.InitBuffer(bS2_, N_*sizeof(float));
120	        p_.InitBuffer(bZ1_, N_*sizeof(float));
121	        p_.InitBuffer(bZ2_, N_*sizeof(float));
122	        p_.InitBuffer(bBi_, N_*sizeof(dataType));
123	
124	        // Work buffers
125	        if constexpr (!std::is_same_v<dataType, float>) {
126	            p_.InitBuffer(bC1_, N_*sizeof(float));
127	            p_.InitBuffer(bC2_, N_*sizeof(float));
128	            p_.InitBuffer(bCB_, N_*sizeof(float));
129	            p_.InitBuffer(bCX_, N_*sizeof(float));
130	        }
131	        p_.InitBuffer(bwA_, N_*sizeof(float));
132	        p_.InitBuffer(bwB_, N_*sizeof(float));
133	        p_.InitBuffer(bwC_, N_*sizeof(float));
134	        p_.InitBuffer(bwD_, N_*sizeof(float));
135	        p_.InitBuffer(bRed_, N_*sizeof(float));
136	        p_.InitBuffer(bSum_, 16*sizeof(float));
137	        p_.InitBuffer(bClp_, N_*sizeof(float));
138	        p_.InitBuffer(bRnd_, N_*sizeof(float));
139	
140	        // Pre-load gamma, beta
141	        gL_ = bGam_.Get<float>();
142	        LoadToUb(gL_, gG_, (uint32_t)N_);
143	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
144	        bL_ = bBet_.Get<float>();
145	        LoadToUb(bL_, bG_, (uint32_t)N_);
146	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
147	
148	        // Pre-load scales
149	        s1L_ = bS1_.Get<float>();
150	        LoadToUb(s1L_, s1G_, (uint32_t)N_);
151	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
152	        s2L_ = bS2_.Get<float>();
153	        LoadToUb(s2L_, s2G_, (uint32_t)N_);
154	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
155	
156	        // Pre-load zero points
157	        z1L_ = bZ1_.Get<float>();
158	        LoadToUb(z1L_, zp1G_, (uint32_t)N_);
159	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
160	        z2L_ = bZ2_.Get<float>();
161	        LoadToUb(z2L_, zp2G_, (uint32_t)N_);
162	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
163	
164	        // Pre-load bias and cast to fp32
165	        biL_ = bBi_.Get<dataType>();
166	        LoadToUb(biL_, biG_, (uint32_t)N_);
167	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
168	        InFp32<dataType>(bFL_, biL_, bCB_, N_);
169	    }
170	
171	    __aicore__ inline void Process()
172	    {
173	        if ASCEND_IS_AIV {
174	            int c = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
175	            int s = AscendC::GetSubBlockIdx();
176	            for (int li = 0; li < tpc_; ++li) {
177	                int bx = c * tpc_ + li;
178	                if (bx * bM_ >= M_) continue;
179	                for (int r = 0; r < sb_; ++r) {
180	                    int row = bx * bM_ + s * sb_ + r;
181	                    if (row < M_) Row(row);
182	                }
183	            }
184	        }
185	    }
186	
187	private:
188	    __aicore__ inline void Row(int32_t row) { CopyIn(row); Comp(); CopyOut(row); }
189	
190	    __aicore__ inline void CopyIn(int32_t row)
191	    {
192	        tX1_ = iQ1_.AllocTensor<dataType>();
193	        LoadToUb(tX1_, x1G_[(uint64_t)row * N_], (uint32_t)N_);
194	        iQ1_.EnQue(tX1_);
195	
196	        tX2_ = iQ2_.AllocTensor<dataType>();
197	        LoadToUb(tX2_, x2G_[(uint64_t)row * N_], (uint32_t)N_);
198	        iQ2_.EnQue(tX2_);
199	    }
200	
201	    __aicore__ inline void Comp()
202	    {
203	        tY1_ = oQY1_.AllocTensor<int8_t>();
204	        tY2_ = oQY2_.AllocTensor<int8_t>();
205	        tXO_ = oQX_.AllocTensor<dataType>();
206	
207	        wA_ = bwA_.Get<float>(); wB_ = bwB_.Get<float>();
208	        wC_ = bwC_.Get<float>(); wD_ = bwD_.Get<float>();
209	        wR_ = bRed_.Get<float>(); wS_ = bSum_.Get<float>();
210	        wL_ = bClp_.Get<float>(); wN_ = bRnd_.Get<float>();
211	
212	        tX1_ = iQ1_.DeQue<dataType>();
213	        tX2_ = iQ2_.DeQue<dataType>();
214	
215	        InFp32<dataType>(x1F_, tX1_, bC1_, N_);
216	        InFp32<dataType>(x2F_, tX2_, bC2_, N_);
217	        OutFp32<dataType>(xoF_, tXO_, bCX_, N_);
218	
219	        // =====================================================================
220	        // Phase 1: Compute x_sum = x1 + x2 + bias, stats
221	        // =====================================================================
222	
223	        AscendC::Add(wA_, x1F_, x2F_, N_);
224	        AscendC::Add(wA_, wA_, bFL_, N_);  // wA_ = x_sum
225	
226	        // Stats: sum(x_sum) and sum(x_sum^2)
227	        AscendC::ReduceSum<float>(wS_, wA_, wR_, N_);
228	        AscendC::PipeBarrier<PIPE_V>();
229	        float sx = wS_.GetValue(0);
230	
231	        wR_ = bRed_.Get<float>();
232	        AscendC::Mul(wB_, wA_, wA_, N_);
233	        AscendC::ReduceSum<float>(wS_, wB_, wR_, N_);
234	        AscendC::PipeBarrier<PIPE_V>();
235	        float sx2 = wS_.GetValue(0);
236	
237	        float inv = 1.0f / (float)N_;
238	        float mv = sx * inv;
239	        float vv = sx2 * inv - mv * mv;
240	
241	        // rstd = 1 / sqrt(var + eps)
242	        AscendC::Duplicate(wS_, vv + eps_, 1);
243	        AscendC::Rsqrt(wS_, wS_, 1);
244	        AscendC::PipeBarrier<PIPE_ALL>();
245	        float rv = wS_.GetValue(0);
246	
247	        // =====================================================================
248	        // Phase 2: LayerNorm: y = (x_sum - mean) * rstd * gamma + beta
249	        // =====================================================================
250	
251	        AscendC::Adds(wB_, wA_, -mv, N_);       // centered = x_sum - mean
252	        AscendC::Muls(wB_, wB_, rv, N_);        // normalized
253	        AscendC::Mul(wC_, wB_, gL_, N_);        // scaled by gamma
254	        AscendC::Add(wD_, wC_, bL_, N_);        // y_norm = scaled + beta
255	        // wD_ = y_norm (LayerNorm output)
256	
257	        // =====================================================================
258	        // Phase 3: x_out = round(x_sum).cast(dtype)
259	        // =====================================================================
260	
261	        // Round x_sum to nearest integer
262	        AscendC::Round(wC_, wA_, wN_, N_);
263	        if constexpr (std::is_same_v<dataType, float>) {
264	            AscendC::DataCopy(xoF_, wC_, N_);
265	        } else {
266	            AscendC::Cast(tXO_, wC_, RMode<dataType>(), N_);
267	            AscendC::PipeBarrier<PIPE_V>();
268	        }
269	        oQX_.EnQue(tXO_);
270	
271	        // =====================================================================
272	        // Phase 4: Dual Quantization
273	        // =====================================================================
274	
275	        // ---- y1 quant ----
276	        // y1_q = div_mode ? y / scale1 : y * scale1
277	        if (divMode_) {
278	            AscendC::Div(wB_, wD_, s1L_, N_);
279	        } else {
280	            AscendC::Mul(wB_, wD_, s1L_, N_);
281	        }
282	        // y1_q += zp1
283	        AscendC::Add(wB_, wB_, z1L_, N_);
284	
285	        // Round to nearest, clamp [-128, 127], cast to int8
286	        AscendC::Round(wC_, wB_, wN_, N_);
287	        AscendC::Duplicate(wL_, -128.0f, N_);
288	        AscendC::PipeBarrier<PIPE_V>();
289	        AscendC::Max(wA_, wC_, wL_, N_);
290	        AscendC::Duplicate(wL_, 127.0f, N_);
291	        AscendC::PipeBarrier<PIPE_V>();
292	        AscendC::Min(wC_, wA_, wL_, N_);
293	        AscendC::Cast(tY1_, wC_, AscendC::RoundMode::CAST_NONE, N_);
294	        AscendC::PipeBarrier<PIPE_V>();
295	        oQY1_.EnQue(tY1_);
296	
297	        // ---- y2 quant ----
298	        if (divMode_) {
299	            AscendC::Div(wB_, wD_, s2L_, N_);
300	        } else {
301	            AscendC::Mul(wB_, wD_, s2L_, N_);
302	        }
303	        AscendC::Add(wB_, wB_, z2L_, N_);
304	
305	        AscendC::Round(wC_, wB_, wN_, N_);
306	        AscendC::Duplicate(wL_, -128.0f, N_);
307	        AscendC::PipeBarrier<PIPE_V>();
308	        AscendC::Max(wA_, wC_, wL_, N_);
309	        AscendC::Duplicate(wL_, 127.0f, N_);
310	        AscendC::PipeBarrier<PIPE_V>();
311	        AscendC::Min(wC_, wA_, wL_, N_);
312	        AscendC::Cast(tY2_, wC_, AscendC::RoundMode::CAST_NONE, N_);
313	        AscendC::PipeBarrier<PIPE_V>();
314	        oQY2_.EnQue(tY2_);
315	
316	        iQ1_.FreeTensor(tX1_);
317	        iQ2_.FreeTensor(tX2_);
318	    }
319	
320	    __aicore__ inline void CopyOut(int32_t row)
321	    {
322	        tY1_ = oQY1_.DeQue<int8_t>();
323	        tY2_ = oQY2_.DeQue<int8_t>();
324	        tXO_ = oQX_.DeQue<dataType>();
325	
326	        StoreToGm(y1G_[(uint64_t)row * N_], tY1_, (uint32_t)N_);
327	        oQY1_.FreeTensor(tY1_);
328	        StoreToGm(y2G_[(uint64_t)row * N_], tY2_, (uint32_t)N_);
329	        oQY2_.FreeTensor(tY2_);
330	        StoreToGm(xoG_[(uint64_t)row * N_], tXO_, (uint32_t)N_);
331	        oQX_.FreeTensor(tXO_);
332	    }
333	
334	    int32_t M_=0, N_=0, bM_=0, uC_=0, tpc_=0, sb_=0;
335	    float eps_=0; int64_t divMode_=0, dtypeFlag_=0;
336	    AscendC::TPipe p_;
337	    AscendC::GlobalTensor<dataType> x1G_, x2G_, biG_, xoG_;
338	    AscendC::GlobalTensor<float> gG_, bG_, s1G_, s2G_, zp1G_, zp2G_;
339	    AscendC::GlobalTensor<int8_t> y1G_, y2G_;
340	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> iQ1_, iQ2_, iQB_;
341	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> oQY1_, oQY2_, oQX_;
342	    AscendC::TBuf<AscendC::TPosition::VECCALC> bGam_, bBet_, bS1_, bS2_, bZ1_, bZ2_, bBi_;
343	    AscendC::TBuf<AscendC::TPosition::VECCALC> bC1_, bC2_, bCB_, bCX_;
344	    AscendC::TBuf<AscendC::TPosition::VECCALC> bwA_, bwB_, bwC_, bwD_, bRed_, bSum_, bClp_, bRnd_;
345	    AscendC::LocalTensor<dataType> tX1_, tX2_, tXO_, biL_;
346	    AscendC::LocalTensor<int8_t> tY1_, tY2_;
347	    AscendC::LocalTensor<float> gL_, bL_, s1L_, s2L_, z1L_, z2L_, bFL_;
348	    AscendC::LocalTensor<float> x1F_, x2F_, xoF_, wA_, wB_, wC_, wD_, wR_, wS_, wL_, wN_;
349	};
350	
351	template <template <typename> class K>
352	__aicore__ inline void Dispatch(
353	    GM_ADDR x1,  GM_ADDR x2,  GM_ADDR g,  GM_ADDR b,  GM_ADDR bi,
354	    GM_ADDR s1,  GM_ADDR s2,  GM_ADDR z1, GM_ADDR z2,
355	    GM_ADDR y1,  GM_ADDR y2,  GM_ADDR xo,
356	    int32_t M,   int32_t N,   int32_t bM, int32_t uC, int32_t tp,
357	    float e,     int64_t dM,  int64_t fl)
358	{
