6	// AscendC DuaQuantizeAddLayerNorm kernel
7	// x1 + x2 + bias -> LayerNorm(gamma, beta) -> Dual Quantize(clamped float) + x_out
8	// Outputs clamped float values; model_new_ascendc.py casts to int8
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
14	// =========================================================================
15	// Helpers
16	// =========================================================================
17	
18	template <typename T>
19	__aicore__ inline void LoadToUb(
20	    AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t n)
21	{
22	    AscendC::DataCopyExtParams cp;
23	    cp.blockCount = 1;
24	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
25	    AscendC::DataCopyPadExtParams<T> pp;
26	    pp.isPad = true;
27	    AscendC::DataCopyPad(dst, src, cp, pp);
28	}
29	
30	template <typename T>
31	__aicore__ inline void StoreToGm(
32	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t n)
33	{
34	    AscendC::DataCopyExtParams cp;
35	    cp.blockCount = 1;
36	    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
37	    AscendC::DataCopyPad(dst, src, cp);
38	}
39	
40	template <typename T>
41	__aicore__ inline AscendC::RoundMode RMode()
42	{
43	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
44	    return AscendC::RoundMode::CAST_NONE;
45	}
46	
47	template <typename T>
48	__aicore__ inline void InFp32(
49	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
50	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
51	{
52	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
53	    else {
54	        d = b.Get<float>();
55	        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
56	        AscendC::PipeBarrier<PIPE_V>();
57	    }
58	}
59	
60	template <typename T>
61	__aicore__ inline void OutFp32(
62	    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
63	    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
64	{
65	    if constexpr (std::is_same_v<T, float>) { d = s.template ReinterpretCast<float>(); }
66	    else { d = b.Get<float>(); AscendC::Duplicate(s, static_cast<T>(0), n); }
67	}
68	
69	// =========================================================================
70	// Kernel
71	// =========================================================================
72	
73	template <typename dataType>
74	class DQALNKernel {
75	public:
76	    __aicore__ inline void Init(
77	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
78	        GM_ADDR s1, GM_ADDR s2, GM_ADDR zp1, GM_ADDR zp2,
79	        GM_ADDR y1, GM_ADDR y2, GM_ADDR xo,
80	        int32_t M, int32_t N, int32_t bM, int32_t uC, int32_t tpc,
81	        float eps, int64_t divMode, int64_t dtypeFlag)
82	    {
83	        M_=M; N_=N; bM_=bM; uC_=uC; tpc_=tpc; eps_=eps;
84	        divMode_=divMode; dtypeFlag_=dtypeFlag;
85	
86	        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), (uint64_t)M*N);
87	        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), (uint64_t)M*N);
88	        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
89	        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
90	        biG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
91	        s1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s1), N);
92	        s2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s2), N);
93	        zp1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp1), N);
94	        zp2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(zp2), N);
95	        y1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y1), (uint64_t)M*N);
96	        y2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y2), (uint64_t)M*N);
97	        xoG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xo), (uint64_t)M*N);
98	
99	        if ASCEND_IS_AIV { BufInit(); }
100	    }
101	
102	    __aicore__ inline void BufInit()
103	    {
104	        sb_ = bM_ / AscendC::GetSubBlockNum();
105	        p_.InitBuffer(iQ1_, BUFFER_NUM, N_*sizeof(dataType));
106	        p_.InitBuffer(iQ2_, BUFFER_NUM, N_*sizeof(dataType));
107	        p_.InitBuffer(oQY1_, BUFFER_NUM, N_*sizeof(float));
108	        p_.InitBuffer(oQY2_, BUFFER_NUM, N_*sizeof(float));
109	        p_.InitBuffer(oQX_, BUFFER_NUM, N_*sizeof(dataType));
110	
111	        // Pre-load static data
112	        p_.InitBuffer(bGam_, N_*sizeof(float));
113	        p_.InitBuffer(bBet_, N_*sizeof(float));
114	        p_.InitBuffer(bS1_, N_*sizeof(float));
115	        p_.InitBuffer(bS2_, N_*sizeof(float));
116	        p_.InitBuffer(bZ1_, N_*sizeof(float));
117	        p_.InitBuffer(bZ2_, N_*sizeof(float));
118	        p_.InitBuffer(bBi_, N_*sizeof(dataType));
119	
120	        // Work buffers
121	        if constexpr (!std::is_same_v<dataType, float>) {
122	            p_.InitBuffer(bC1_, N_*sizeof(float));
123	            p_.InitBuffer(bC2_, N_*sizeof(float));
124	            p_.InitBuffer(bCB_, N_*sizeof(float));
125	            p_.InitBuffer(bCX_, N_*sizeof(float));
126	        }
127	        p_.InitBuffer(bwA_, N_*sizeof(float));
128	        p_.InitBuffer(bwB_, N_*sizeof(float));
129	        p_.InitBuffer(bwC_, N_*sizeof(float));
130	        p_.InitBuffer(bwD_, N_*sizeof(float));
131	        p_.InitBuffer(bRed_, N_*sizeof(float));
132	        p_.InitBuffer(bSum_, 16*sizeof(float));
133	        p_.InitBuffer(bClp_, N_*sizeof(float));
134	        p_.InitBuffer(bRnd_, N_*sizeof(float));
135	
136	        // Pre-load gamma, beta
137	        gL_ = bGam_.Get<float>();
138	        LoadToUb(gL_, gG_, (uint32_t)N_);
139	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
140	        bL_ = bBet_.Get<float>();
141	        LoadToUb(bL_, bG_, (uint32_t)N_);
142	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
143	
144	        // Pre-load scales
145	        s1L_ = bS1_.Get<float>();
146	        LoadToUb(s1L_, s1G_, (uint32_t)N_);
147	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
148	        s2L_ = bS2_.Get<float>();
149	        LoadToUb(s2L_, s2G_, (uint32_t)N_);
150	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
151	
152	        // Pre-load zero points
153	        z1L_ = bZ1_.Get<float>();
154	        LoadToUb(z1L_, zp1G_, (uint32_t)N_);
155	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
156	        z2L_ = bZ2_.Get<float>();
157	        LoadToUb(z2L_, zp2G_, (uint32_t)N_);
158	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
159	
160	        // Pre-load bias and cast to fp32
161	        biL_ = bBi_.Get<dataType>();
162	        LoadToUb(biL_, biG_, (uint32_t)N_);
163	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
164	        InFp32<dataType>(bFL_, biL_, bCB_, N_);
165	    }
166	
167	    __aicore__ inline void Process()
168	    {
169	        if ASCEND_IS_AIV {
170	            int c = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
171	            int s = AscendC::GetSubBlockIdx();
172	            for (int li = 0; li < tpc_; ++li) {
173	                int bx = c * tpc_ + li;
174	                if (bx * bM_ >= M_) continue;
175	                for (int r = 0; r < sb_; ++r) {
176	                    int row = bx * bM_ + s * sb_ + r;
177	                    if (row < M_) Row(row);
178	                }
179	            }
180	        }
181	    }
182	
183	private:
184	    __aicore__ inline void Row(int32_t row) { CopyIn(row); Comp(); CopyOut(row); }
185	
186	    __aicore__ inline void CopyIn(int32_t row)
187	    {
188	        tX1_ = iQ1_.AllocTensor<dataType>();
189	        LoadToUb(tX1_, x1G_[(uint64_t)row * N_], (uint32_t)N_);
190	        iQ1_.EnQue(tX1_);
191	
192	        tX2_ = iQ2_.AllocTensor<dataType>();
193	        LoadToUb(tX2_, x2G_[(uint64_t)row * N_], (uint32_t)N_);
194	        iQ2_.EnQue(tX2_);
195	    }
196	
197	    __aicore__ inline void Comp()
198	    {
199	        tY1_ = oQY1_.AllocTensor<float>();
200	        tY2_ = oQY2_.AllocTensor<float>();
201	        tXO_ = oQX_.AllocTensor<dataType>();
202	
203	        wA_ = bwA_.Get<float>(); wB_ = bwB_.Get<float>();
204	        wC_ = bwC_.Get<float>(); wD_ = bwD_.Get<float>();
205	        wR_ = bRed_.Get<float>(); wS_ = bSum_.Get<float>();
206	        wL_ = bClp_.Get<float>(); wN_ = bRnd_.Get<float>();
207	
208	        tX1_ = iQ1_.DeQue<dataType>();
209	        tX2_ = iQ2_.DeQue<dataType>();
210	
211	        InFp32<dataType>(x1F_, tX1_, bC1_, N_);
212	        InFp32<dataType>(x2F_, tX2_, bC2_, N_);
213	        OutFp32<dataType>(xoF_, tXO_, bCX_, N_);
214	
215	        // =====================================================================
216	        // Phase 1: Compute x_sum = x1 + x2 + bias, stats
217	        // =====================================================================
218	
219	        AscendC::Add(wA_, x1F_, x2F_, N_);
220	        AscendC::Add(wA_, wA_, bFL_, N_);  // wA_ = x_sum
221	
222	        // Stats: sum(x_sum) and sum(x_sum^2)
223	        AscendC::ReduceSum<float>(wS_, wA_, wR_, N_);
224	        AscendC::PipeBarrier<PIPE_V>();
225	        float sx = wS_.GetValue(0);
226	
227	        wR_ = bRed_.Get<float>();
228	        AscendC::Mul(wB_, wA_, wA_, N_);
229	        AscendC::ReduceSum<float>(wS_, wB_, wR_, N_);
230	        AscendC::PipeBarrier<PIPE_V>();
231	        float sx2 = wS_.GetValue(0);
232	
233	        float inv = 1.0f / (float)N_;
234	        float mv = sx * inv;
235	        float vv = sx2 * inv - mv * mv;
236	
237	        // rstd = 1 / sqrt(var + eps)
238	        AscendC::Duplicate(wS_, vv + eps_, 1);
239	        AscendC::Rsqrt(wS_, wS_, 1);
240	        AscendC::PipeBarrier<PIPE_ALL>();
241	        float rv = wS_.GetValue(0);
242	
243	        // =====================================================================
244	        // Phase 2: LayerNorm: y = (x_sum - mean) * rstd * gamma + beta
245	        // =====================================================================
246	
247	        AscendC::Adds(wB_, wA_, -mv, N_);       // centered = x_sum - mean
248	        AscendC::Muls(wB_, wB_, rv, N_);        // normalized
249	        AscendC::Mul(wC_, wB_, gL_, N_);        // scaled by gamma
250	        AscendC::Add(wD_, wC_, bL_, N_);        // y_norm = scaled + beta
251	        // wD_ = y_norm (LayerNorm output)
252	
253	        // =====================================================================
254	        // Phase 3: x_out = round(x_sum).cast(dtype)
255	        // =====================================================================
256	
257	        // Round x_sum to nearest integer
258	        AscendC::Round(wC_, wA_, wN_, N_);
259	        if constexpr (std::is_same_v<dataType, float>) {
260	            AscendC::DataCopy(xoF_, wC_, N_);
261	        } else {
262	            AscendC::Cast(tXO_, wC_, RMode<dataType>(), N_);
263	            AscendC::PipeBarrier<PIPE_V>();
264	        }
265	        oQX_.EnQue(tXO_);
266	
267	        // =====================================================================
268	        // Phase 4: Dual Quantization (output clamped float)
269	        // =====================================================================
270	
271	        // ---- y1 quant ----
272	        if (divMode_) {
273	            AscendC::Div(wB_, wD_, s1L_, N_);
274	        } else {
275	            AscendC::Mul(wB_, wD_, s1L_, N_);
276	        }
277	        AscendC::Add(wB_, wB_, z1L_, N_);               // y1_q
278	
279	        // Round to nearest, clamp [-128, 127] as float
280	        AscendC::Round(wC_, wB_, wN_, N_);
281	        AscendC::Duplicate(wL_, -128.0f, N_);
282	        AscendC::PipeBarrier<PIPE_V>();
283	        AscendC::Max(wA_, wC_, wL_, N_);
284	        AscendC::Duplicate(wL_, 127.0f, N_);
285	        AscendC::PipeBarrier<PIPE_V>();
286	        AscendC::Min(tY1_, wA_, wL_, N_);
287	        oQY1_.EnQue(tY1_);
288	
289	        // ---- y2 quant ----
290	        if (divMode_) {
291	            AscendC::Div(wB_, wD_, s2L_, N_);
292	        } else {
293	            AscendC::Mul(wB_, wD_, s2L_, N_);
294	        }
295	        AscendC::Add(wB_, wB_, z2L_, N_);               // y2_q
296	
297	        AscendC::Round(wC_, wB_, wN_, N_);
298	        AscendC::Duplicate(wL_, -128.0f, N_);
299	        AscendC::PipeBarrier<PIPE_V>();
300	        AscendC::Max(wA_, wC_, wL_, N_);
301	        AscendC::Duplicate(wL_, 127.0f, N_);
302	        AscendC::PipeBarrier<PIPE_V>();
303	        AscendC::Min(tY2_, wA_, wL_, N_);
304	        oQY2_.EnQue(tY2_);
305	
306	        iQ1_.FreeTensor(tX1_);
307	        iQ2_.FreeTensor(tX2_);
308	    }
309	
310	    __aicore__ inline void CopyOut(int32_t row)
311	    {
312	        tY1_ = oQY1_.DeQue<float>();
313	        tY2_ = oQY2_.DeQue<float>();
314	        tXO_ = oQX_.DeQue<dataType>();
315	
316	        StoreToGm(y1G_[(uint64_t)row * N_], tY1_, (uint32_t)N_);
317	        oQY1_.FreeTensor(tY1_);
318	        StoreToGm(y2G_[(uint64_t)row * N_], tY2_, (uint32_t)N_);
319	        oQY2_.FreeTensor(tY2_);
320	        StoreToGm(xoG_[(uint64_t)row * N_], tXO_, (uint32_t)N_);
321	        oQX_.FreeTensor(tXO_);
322	    }
323	
324	    int32_t M_=0, N_=0, bM_=0, uC_=0, tpc_=0, sb_=0;
325	    float eps_=0; int64_t divMode_=0, dtypeFlag_=0;
326	    AscendC::TPipe p_;
327	    AscendC::GlobalTensor<dataType> x1G_, x2G_, biG_, xoG_;
328	    AscendC::GlobalTensor<float> gG_, bG_, s1G_, s2G_, zp1G_, zp2G_, y1G_, y2G_;
329	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> iQ1_, iQ2_;
330	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> oQY1_, oQY2_, oQX_;
331	    AscendC::TBuf<AscendC::TPosition::VECCALC> bGam_, bBet_, bS1_, bS2_, bZ1_, bZ2_, bBi_;
332	    AscendC::TBuf<AscendC::TPosition::VECCALC> bC1_, bC2_, bCB_, bCX_;
333	    AscendC::TBuf<AscendC::TPosition::VECCALC> bwA_, bwB_, bwC_, bwD_, bRed_, bSum_, bClp_, bRnd_;
334	    AscendC::LocalTensor<dataType> tX1_, tX2_, tXO_, biL_;
335	    AscendC::LocalTensor<float> tY1_, tY2_;
336	    AscendC::LocalTensor<float> gL_, bL_, s1L_, s2L_, z1L_, z2L_, bFL_;
337	    AscendC::LocalTensor<float> x1F_, x2F_, xoF_, wA_, wB_, wC_, wD_, wR_, wS_, wL_;
338	};
339	
340	template <template <typename> class K>
341	__aicore__ inline void Dispatch(
342	    GM_ADDR x1,  GM_ADDR x2,  GM_ADDR g,  GM_ADDR b,  GM_ADDR bi,
343	    GM_ADDR s1,  GM_ADDR s2,  GM_ADDR z1, GM_ADDR z2,
344	    GM_ADDR y1,  GM_ADDR y2,  GM_ADDR xo,
345	    int32_t M,   int32_t N,   int32_t bM, int32_t uC, int32_t tp,
346	    float e,     int64_t dM,  int64_t fl)
347	{
348	    if (fl == 0) {
349	        K<float> k;
350	        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
351	        k.Process();
352	    } else if (fl == 1) {
353	        K<half> k;
354	        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
355	        k.Process();
356	    } else {
357	        K<bfloat16_t> k;
358	        k.Init(x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
359	        k.Process();
360	    }
361	}
362	
363	extern "C" __global__ __aicore__ void dua_quantize_add_layernorm(
364	    GM_ADDR x1,  GM_ADDR x2,  GM_ADDR g,  GM_ADDR b,  GM_ADDR bi,
365	    GM_ADDR s1,  GM_ADDR s2,  GM_ADDR z1, GM_ADDR z2,
366	    GM_ADDR y1,  GM_ADDR y2,  GM_ADDR xo,
367	    int32_t M,   int32_t N,   int32_t bM, int32_t uC, int32_t tp,
368	    float e,     int64_t dM,  int64_t fl)
369	{
370	    Dispatch<DQALNKernel>(
371	        x1, x2, g, b, bi, s1, s2, z1, z2, y1, y2, xo, M, N, bM, uC, tp, e, dM, fl);
372	}
